package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.nio.file.Files;
import java.nio.file.Path;

import org.eclipse.rdf4j.model.TripleTerm;
import org.eclipse.rdf4j.model.Value;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.rio.helpers.BasicParserSettings;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class LmdbBlankNodeLoadAllocationTest {

	@Test
	void loadOrdinaryBlanksAvoidLaterReferencesAndDestinationGraphIdentity(@TempDir Path directory) throws Exception {
		var vf = SimpleValueFactory.getInstance();
		for (int variant = 0; variant < 4; variant++) {
			boolean nested = (variant & 1) != 0;
			boolean named = (variant & 2) != 0;
			Path document = directory.resolve("load-" + variant + ".ttl");
			Files.writeString(document, nested
					? "<urn:s> <urn:loaded> <<(<urn:inner> <urn:p> _:future)>> ."
					: "_:future <urn:loaded> \"loaded\" .");
			var repository = new SailRepository(
					new LmdbStore(Files.createDirectory(directory.resolve("store-" + variant)).toFile()));
			repository.init();
			try (var connection = repository.getConnection()) {
				connection.getParserConfig().set(BasicParserSettings.PRESERVE_BNODE_IDS, true);
				connection.prepareUpdate("LOAD <" + document.toUri() + ">"
						+ (named ? " INTO GRAPH <_:future>" : "")
						+ "; INSERT DATA { <_:future> <urn:fixed> \"fixed\" }").execute();
				try (var statements = connection.getStatements(null, vf.createIRI("urn:loaded"), null, false)) {
					assertTrue(statements.hasNext());
					var statement = statements.next();
					Value imported = nested ? ((TripleTerm) statement.getObject()).getObject() : statement.getSubject();
					assertNotEquals(vf.createBNode("future"), imported);
					if (named) {
						assertEquals(vf.createBNode("future"), statement.getContext());
					}
					assertFalse(statements.hasNext());
				}
				assertTrue(connection.hasStatement(vf.createBNode("future"), vf.createIRI("urn:fixed"),
						vf.createLiteral("fixed"), false));
			} finally {
				repository.shutDown();
			}
		}
	}
}
